const makePrompt = (title: string, kind: string, duration: string, index: number) => title === "Viral Baby Videos Creating Prompt" ? attachedBabyPrompt : title === "Ulti Dunya: Reverse Animal World" ? reverseAnimalPrompt : missingVisualPrompts[title] ? missingVisualPrompts[title] : `You are a senior AI video prompt engineer, visual director, continuity supervisor, cinematographer, production designer, sound designer, and quality-control editor. Create an ultra-detailed, production-ready ${title} prompt for a ${duration} ${kind.toLowerCase()} production. Do not return a vague concept. Return operational instructions an image-to-video or text-to-video model can execute.

1. CREATIVE BRIEF AND VARIABLES
Category: ${title}
Duration: ${duration}
Prompt type: ${kind}
Primary subject: [SUBJECT]
Target audience: [TARGET AUDIENCE]
Platform: [PLATFORM]
Style and emotional intent: [STYLE]
Location: [LOCATION]
Brand or product: [BRAND / PRODUCT]
Offer or message: [OFFER / MESSAGE]
Spoken language and dialogue: [LANGUAGE / DIALOGUE]
Reference image(s): [REFERENCE IMAGE(S)]
Aspect ratio and resolution: [ASPECT RATIO / RESOLUTION]

2. INPUT ANALYSIS BEFORE GENERATION
If a reference image is supplied, first analyze and preserve the subject identity, face or species features, age, body proportions, clothing, accessories, product geometry, logo shape, color palette, camera angle, lens impression, lighting direction, shadows, reflections, environment, and visible text. Separate observed facts from assumptions. If information is missing, use conservative defaults and state them. Never invent a logo, claim, identity, or product feature.

3. LOCKED CONTINUITY BIBLE
Before Scene 1, define a locked character or product bible: exact face or product geometry, height and proportions, skin, fur, feathers or materials, hairstyle, wardrobe, accessories, signature props, voice, movement style, color palette, and emotional baseline. Define the environment bible: floor plan, horizon, fixed furniture, architecture, time of day, weather, light direction, color grade, ambient atmosphere, and persistent background elements. Define object state and screen direction. Reuse the same references in every scene; never redesign a locked subject, wardrobe, prop, product, environment, voice, or lighting logic.

4. STORY AND SCENE ARCHITECTURE
Build connected maximum-10-second scenes for the selected duration. Scene 1 must establish a strong visual hook within the first two seconds. Each scene has one clear objective, one readable action, one emotional beat, exact dialogue or narration when required, purposeful camera direction, sound cues, and a precise ending state. The ending pose, gaze, hand position, object state, screen direction, lighting, and emotional beat of Scene N must become the starting state of Scene N+1. Explain any location change naturally. Do not generate disconnected montage shots, unexplained extras, prop drift, or continuity resets.

5. VISUAL DIRECTION
Specify composition, focal hierarchy, foreground/midground/background separation, camera height, shot size, lens, depth of field, camera movement, focus behavior, subject blocking, lighting ratio, practical lights, color grade, materials, texture, atmospheric depth, contact shadows, reflections, motion blur, and realistic physics. Use premium cinematic visual storytelling while keeping the primary subject legible. For animation, specify deliberate motion, facial expression, eye lines, hand and body mechanics, weight shifts, cloth and hair movement, and natural contact with the environment.

6. AUDIO AND DIALOGUE
Specify dialogue or narration only when the category needs it. Keep dialogue concise enough for the scene duration, assign every line to the correct speaker, and require natural synchronized lip-sync. Specify voice age, accent, emotion, pacing, pauses, ambience, Foley, environmental sound, and transitions. Do not add music, captions, subtitles, logos, or watermarks unless the brief explicitly requests them.

7. PLATFORM AND OUTPUT SPECIFICATION
Optimize for [PLATFORM] and state the final aspect ratio, pixel dimensions, frame rate, duration, safe zones, export format, and intended placement. Default guidance: 9:16 for Shorts, Reels, TikTok, and Stories; 16:9 for YouTube landscape, banners, and cinematic widescreen; 1:1 for square feeds; 4:5 for portrait feeds. Keep faces, products, logos, and text within conservative safe margins. If typography is requested, reproduce [TEXT] exactly, with clean spelling, hierarchy, contrast, line breaks, padding, and legibility at thumbnail size. Never create pseudo-text.

8. NEGATIVE PROMPT AND ARTIFACT PREVENTION
No identity drift, face morphing, species change, product redesign, wrong logo, misspelled text, extra fingers, broken hands, malformed eyes, plastic skin, duplicated subjects, floating objects, disconnected shadows, impossible reflections, warped perspective, hard mask halos, edge fringing, flicker, jitter, temporal popping, frame interpolation artifacts, random camera cuts, unexplained characters, prop drift, inconsistent wardrobe, inconsistent lighting, low-detail textures, oversharpening, banding, compression noise, accidental watermark, subtitles, captions, or unrequested claims.

9. FINAL RESPONSE FORMAT
A. Task interpretation and assumptions.
B. Locked character/product bible.
C. Locked environment and continuity bible.
D. Scene-by-scene production prompts with timestamps, action, camera, lighting, dialogue, SFX, ending state, and next-scene handoff.
E. Platform, aspect ratio, resolution, frame rate, safe zones, and export specification.
F. Concise negative prompt.
G. Quality-control checklist confirming subject consistency, scene continuity, composition, anatomy, text accuracy, sound synchronization, platform fit, and artifact prevention.
H. Two or three controlled creative variations that change only the requested creative variable.

FINAL COMMAND
Follow the category direction exactly: ${title}. Prioritize clarity, continuity, believable motion, intentional composition, production feasibility, and high-end commercial quality. Never shorten the requested production output into a one-line idea.`;
const allCategoryCards: CategoryCard[] = titles.map((title, index) => { const duration = index % 4 === 0 ? "60 sec" : index % 4 === 1 ? "2 min" : index % 4 === 2 ? "3 min" : "5 min"; const kind = chooseKind(title); return { id: index + 1, title, description: `A ready-made ${title.toLowerCase()} prompt with a clear visual hook, production direction, and scene-ready structure.`, kind, image: chooseRealImage(title, index), accent: accents[index % accents.length], duration, prompt: makePrompt(title, kind, duration, index) }; });

const previewCards = allCategoryCards.filter((card) => card.title === "Viral Baby Videos Creating Prompt" || card.title === "Ulti Dunya: Reverse Animal World");
const remainingCards = allCategoryCards.filter((card) => !previewCards.includes(card));
export const categoryCards: CategoryCard[] = [...previewCards, ...remainingCards].map((card, index) => ({ ...card, id: index + 1 }));
